(function(){"use strict";var CFG={owner:"Cool-zimo",repo:"drive-bans",file:"bans.json",cleanup:"cleanup.json",marker:".gd-ban.json",stateDir:"state",author:"cool-zimo",maxRepos:12};function api(){var a=window.app&&window.app.api;if(!a)throw new Error("\u672A\u767B\u5F55");return a}function me(){try{return(window.app&&window.app.storage&&window.app.storage.getUser()||{}).login||""}catch{return""}}function isAuthor(){return(me()||"").toLowerCase()===CFG.author}function nowMs(){return Date.now()}function b64(s){return btoa(unescape(encodeURIComponent(s)))}function unb64(s){try{return decodeURIComponent(escape(atob(String(s||"").replace(/\s/g,""))))}catch{return""}}async function rawJson(file){try{var url="https://raw.githubusercontent.com/"+CFG.owner+"/"+CFG.repo+"/main/"+file+"?t="+nowMs(),r=await fetch(url,{cache:"no-store"});return r.ok?await r.json():null}catch{return null}}async function getFile(owner,repo,path){try{var got=await api().request("/repos/"+owner+"/"+repo+"/contents/"+path);return{sha:got.sha,obj:JSON.parse(unb64(got.content))}}catch{return null}}async function putFile(owner,repo,path,obj,msg,sha){var body={message:msg,content:b64(JSON.stringify(obj,null,2))};return sha&&(body.sha=sha),await api().request("/repos/"+owner+"/"+repo+"/contents/"+path,{method:"PUT",body:JSON.stringify(body)})}async function delFile(owner,repo,path,sha,msg){return await api().request("/repos/"+owner+"/"+repo+"/contents/"+path,{method:"DELETE",body:JSON.stringify({message:msg,sha})})}function myRepos(){var list=[];try{for(var u=me(),rs=window.app&&window.app.storage&&window.app.storage.getRepos?window.app.storage.getRepos():[],i=0;i<rs.length;i++){var r=rs[i]||{};!r.owner||!r.repo||u&&String(r.owner).toLowerCase()!==String(u).toLowerCase()||list.push({owner:r.owner,repo:r.repo})}}catch{}return list.slice(0,CFG.maxRepos)}var Bans={async list(){var j=await rawJson(CFG.file);return j&&Array.isArray(j.bans)?j.bans:[]},find(bans,login){for(var k=String(login||"").toLowerCase(),i=0;i<bans.length;i++)if(String(bans[i]&&bans[i].user||"").toLowerCase()===k)return bans[i];return null},async cleanupList(){var j=await rawJson(CFG.cleanup);return j&&Array.isArray(j.pending)?j.pending:[]}};async function seal(login,hit,end){var repos=myRepos();if(!repos.length)return 0;for(var payload={v:1,user:login,reason:hit.reason||"\u8FDD\u53CD\u793E\u533A\u89C4\u5219",by:hit.by||CFG.author,days:Number(hit.days)||3,seenAt:Number(hit.seenAt)||0,until:end,updatedAt:new Date().toISOString()},n=0,i=0;i<repos.length;i++)try{var cur=await getFile(repos[i].owner,repos[i].repo,CFG.marker);if(cur&&cur.obj&&Number(cur.obj.until)===end)continue;await putFile(repos[i].owner,repos[i].repo,CFG.marker,payload,"chore: sync account state",cur?cur.sha:null),n++}catch{}return n}async function sweep(){var repos=myRepos();if(!repos.length)return 0;for(var n=0,i=0;i<repos.length;i++)try{var cur=await getFile(repos[i].owner,repos[i].repo,CFG.marker);if(!cur)continue;await delFile(repos[i].owner,repos[i].repo,CFG.marker,cur.sha,"chore: clear expired account state"),n++}catch{}return n}async function hasMarker(){for(var repos=myRepos(),i=0;i<repos.length;i++)try{if(await getFile(repos[i].owner,repos[i].repo,CFG.marker))return!0}catch{}return!1}async function reportSeen(login,seen){try{var path=CFG.stateDir+"/"+String(login).toLowerCase()+".json",payload={user:login,seenAt:seen,at:new Date().toISOString()};try{var cur=await getFile(CFG.owner,CFG.repo,path);return await putFile(CFG.owner,CFG.repo,path,payload,"state: "+login+" seen ban notice",cur?cur.sha:null),!0}catch{}await api().request("/repos/"+CFG.owner+"/"+CFG.repo+"/forks",{method:"POST",body:"{}"});var meLogin=me(),head="state-"+String(login).toLowerCase()+"-"+String(seen).slice(-6);try{var base=await api().request("/repos/"+CFG.owner+"/"+CFG.repo),sha=(await api().request("/repos/"+CFG.owner+"/"+CFG.repo+"/git/ref/heads/"+(base.default_branch||"main"))).object.sha;await api().request("/repos/"+meLogin+"/"+CFG.repo+"/git/refs",{method:"POST",body:JSON.stringify({ref:"refs/heads/"+head,sha})})}catch{}return await putFile(meLogin,CFG.repo,path,payload,"state: record ban notice time",null),await api().request("/repos/"+CFG.owner+"/"+CFG.repo+"/pulls",{method:"POST",body:JSON.stringify({title:"state: "+login,head:meLogin+":"+head,base:"main",body:"\u81EA\u52A8\u4E0A\u62A5\u5C01\u7981\u53D1\u73B0\u65F6\u523B"})}),!0}catch{return!1}}async function reportCleaned(login){try{var j=await rawJson(CFG.cleanup);if(!j||!Array.isArray(j.pending))return!1;var k=String(login).toLowerCase(),left=j.pending.filter(function(x){return String(x).toLowerCase()!==k});if(left.length===j.pending.length)return!1;var cur=await getFile(CFG.owner,CFG.repo,CFG.cleanup);return cur?(await putFile(CFG.owner,CFG.repo,CFG.cleanup,{pending:left},"cleanup: "+login+" cleared",cur.sha),!0):!1}catch{return!1}}async function resolve(){var u=me();if(!u||isAuthor())return null;var key=u.toLowerCase(),LS="gd_ban_start_"+key,bans=await Bans.list(),hit=Bans.find(bans,u);if(!hit){try{localStorage.removeItem(LS)}catch{}var pending=await Bans.cleanupList(),inPending=pending.some(function(x){return String(x).toLowerCase()===key});return inPending?(await sweep(),await reportCleaned(u)):await hasMarker()&&await sweep(),null}var seen=Number(hit.seenAt||0);if(seen)try{localStorage.setItem(LS,String(seen))}catch{}else{var st=null;try{st=localStorage.getItem(LS)}catch{}seen=st?Number(st):nowMs();try{localStorage.setItem(LS,String(seen))}catch{}reportSeen(u,seen)}var days=Number(hit.days)||3,end=Number(hit.expireAt||0)||seen+days*864e5,now=nowMs();if(now>=end){try{localStorage.removeItem(LS)}catch{}return await sweep(),await reportCleaned(u),null}return seal(u,hit,end),{user:u,reason:hit.reason||"\u8FDD\u53CD\u793E\u533A\u89C4\u5219",by:hit.by||CFG.author,days,end,remain:end-now,seenAt:seen}}window.GdBan={CFG,resolve,seal,sweep,hasMarker,reportSeen,list:function(){return Bans.list()},cleanupList:function(){return Bans.cleanupList()}}})();
